// AssertMixedContract runs every generated check against every declared subject.
//
//	Subjects: declare each with MixedSubject
//	Extend:   MixedOnApply, MixedOnTotal
//	Drop:     MixedWithout, by the path each check reports under
func AssertMixedContract(t *testing.T, opts ...MixedOption) {
	t.Helper()
	cfg := newMixedConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertMixedContract was given no subject; declare one with " +
			"MixedSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("MixedWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runMixedChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runMixedChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runMixedChecks(
	t *testing.T,
	cfg *mixedConfig,
	label string,
	factory func() associative.Mixed,
	wrap func(tb testing.TB, subject associative.Mixed) associative.Mixed,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(mixedApply, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onApply {
				cfg.run(t, string(suite.MethodID(mixedApply, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Delta)
				})
			}
		})

		t.Run(mixedTotal, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onTotal {
				cfg.run(t, string(suite.MethodID(mixedTotal, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through MixedWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

